INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(16701, 'Isaiah 8:3', 'Isaiah', 8, 3, '&nbsp;بيا زۀ د خپلې پېغمبرې ښځې سره څملاستم، هغه اُميدواره شوه او يو زوئ مو پېدا شو، نو مالِک خُدائ ما ته وفرمائيل، ”په هغۀ باندې ”د تېزۍ مال غنيمت او زر زر لوټ مار“ نوم کېږده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16702, 'Isaiah 8:4', 'Isaiah', 8, 4, '&nbsp;د هغې نه وړاندې چې ماشوم دومره لوئ شى چې ابو او امى وئيلے شى، نو د دمشق ټول مال دولت او د سامريه ټول مال غنيمت به د اسور بادشاه لوټ کړے وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16703, 'Isaiah 8:5', 'Isaiah', 8, 5, '&nbsp;نو مالِک خُدائ يو ځل بيا ما سره کلام وکړو. هغۀ وفرمائيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16704, 'Isaiah 8:6', 'Isaiah', 8, 6, '&nbsp;”دې خلقو د شيلوخ قلارې روانې اوبۀ رد کړې دى او د رضين بادشاه او فقح بادشاه نه يرېدلى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16705, 'Isaiah 8:7', 'Isaiah', 8, 7, '&nbsp;نو په دې وجه به زۀ، مالِک خُدائ د اسور بادشاه او د هغۀ ټول لښکر راولم چې په يهوداه حمله وکړى. د هغۀ لښکر به داسې وړاندې راشى لکه چې د فرات د سيند اوبۀ د غاړو نه راوړېدلې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16706, 'Isaiah 8:8', 'Isaiah', 8, 8, '&nbsp;هغوئ به د سېلاب په شکل کښې د يهوداه نه تېر شى، اے عمانو‌ايله، اوبۀ به لکه د مرغۍ د وزرو په شان خوَرې وى او ستا ټول مُلک به يې نيولے وى. او خلق به يې تر مرۍ مرۍ پورې پټ کړى وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16707, 'Isaiah 8:9', 'Isaiah', 8, 9, '&nbsp;اے قومونو، په يره يره کښې راغونډ شئ. اے د دُنيا لرې مُلکونو واورئ. د جنګ دپاره تيار شئ، خو تاسو به چخڼى کړے شئ. آو، تيار شئ، خو تاسو به چخڼى کړے شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16708, 'Isaiah 8:10', 'Isaiah', 8, 10, '&nbsp;تاسو چې څۀ منصوبې هم جوړَوئ هغه به بې‌فائدې وى. تاسو چې څۀ فېصله هم کوئ هغه به ناکام کيږى، ځکه چې خُدائ پاک زمونږ مل دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16709, 'Isaiah 8:11', 'Isaiah', 8, 11, '&nbsp;مالِک خُدائ زۀ کلک ونيولم او خبردارے يې راکړو چې په هغه لار به نۀ ځې چې په کومه به نور خلق تلل. هغۀ وفرمائيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16710, 'Isaiah 8:12', 'Isaiah', 8, 12, '&nbsp;”هره خبره سازش مۀ ګڼه څنګه چې يې دا قوم ګڼى او د هغه څيزونو نه مۀ يرېږه چې کوم نه دوئ يريږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16711, 'Isaiah 8:13', 'Isaiah', 8, 13, '&nbsp;مالِک خُدائ، ربُ الافواج مقدس ګڼئ، د هغۀ نه دهشت خورئ او د هغۀ نه يره کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16712, 'Isaiah 8:14', 'Isaiah', 8, 14, '&nbsp;بيا به هغه تاسو محفوظ ساتى. خو هغه به د اِسرائيل او د يهوداه دپاره يو داسې کاڼے وى چې د تيندک باعث به جوړيږى، او خلق به پرې تيندک وخورى او راوبه غورزيږى. او د يروشلم د خلقو دپاره به هغه يو دام او يو جال جوړ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16713, 'Isaiah 8:15', 'Isaiah', 8, 15, '&nbsp;په هغوئ کښې به ډېر تيندک وخورى راوبه غورزيږى او ټوټې ټوټې به شى. هغوئ به په دام کښې راګېر شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16714, 'Isaiah 8:16', 'Isaiah', 8, 16, '&nbsp;د څۀ تعليم چې ما ورکړو، نو هغه دې په طومار کښې درج کړے شى او زما شاګردانو له دې ورکړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16715, 'Isaiah 8:17', 'Isaiah', 8, 17, '&nbsp;زۀ به د مالِک خُدائ انتظار کوم او د هغۀ نه به اُميد ساتم، اګر چې هغۀ د يعقوب خاندان رد کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16716, 'Isaiah 8:18', 'Isaiah', 8, 18, '&nbsp;زۀ دلته د هغه بچو سره يم چې کوم مالِک خُدائ ما له راکړى دى. هغه مالِک خُدائ، ربُ الافواج چې د هغۀ تخت د صيون په غر باندې دے، هغۀ مونږ اِسرائيل له د نښې او خبردارى په توګه رالېږلى يُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16717, 'Isaiah 8:19', 'Isaiah', 8, 19, '&nbsp;کۀ څوک تاسو ته ووائى چې، ”د قسمت ښودونکو او مړو روحونو سره خبرو والا نه پته وکړئ، د هغوئ نه چې په نرى آواز سره يا په ګونګسو کښې خبرې کوى،“ هغوئ به وائى، ”د هر څۀ نه به ښۀ نۀ وى چې خلق د خپلو معبودانو سره مشوره وکړى؟ د ژوندو د خاطره مونږ د مړو د روحونو سره ولې مشوره ونۀ کړُو؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16718, 'Isaiah 8:20', 'Isaiah', 8, 20, '&nbsp;د مالِک خُدائ هداياتو او تعليماتو ته ګورئ. هغه خلق څوک چې د هغۀ د کلام په مطابق پېغام نۀ اوروى نو د هغوئ مستقبل ښۀ نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16719, 'Isaiah 8:21', 'Isaiah', 8, 21, '&nbsp;هغوئ به په هغه مُلک کښې سرګردانه ګرځى، اوږى او بې‌حوصلې به وى. د لوږې نه به غصه وى او خپل بادشاه او خُدائ پاک ته به کنځل کوى. هغوئ کۀ آسمان ته سترګې پورته کړى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16720, 'Isaiah 8:22', 'Isaiah', 8, 22, '&nbsp;يا کۀ زمکې ته ګورى، خو هغوئ ته به د پرېشانۍ، مصيبت او تيارې نه بغېر هيڅ هم نۀ ښکارى، په تکه توره او يروونکې تيارۀ کښې به وغورزولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16721, 'Isaiah 9:1', 'Isaiah', 9, 1, '&nbsp;نو د هغوئ دپاره به دا مصيبت تر همېشه پورې جارى نۀ وى. د زبولون او نفتالى علاقه ته په يو وخت کښې سپک کتلے شول، خو په راتلونکى وخت کښې به دا علاقه عزتمنده شى، نمرخاتۀ طرف ته د مديترانى سمندر نه واخله د درياب طرف ته د اُردن نه پورې او داسې ګليل به هم عزتمند شى، چرته چې غېر‌يهوديان اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16722, 'Isaiah 9:2', 'Isaiah', 9, 2, '&nbsp;کوم خلق چې په تيارۀ کښې ګرځېدل، نو هغوئ يوه لويه رڼا ليدلې ده، او هغوئ څوک چې په تورو تيارو کښې اوسېدل، پرې نُور ځليږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16723, 'Isaiah 9:3', 'Isaiah', 9, 3, '&nbsp;تا د هغوئ قوم لوئ کړے دے او لويه خوشحالى دې ورکړې ده. تا چې څۀ کړى دى نو په هغې باندې هغوئ خوشحالى کوى، هغوئ دومره خوشحالى کوى لکه چې خلق يې د فصل د رېبلو په وخت کوى، او يا چې کله مالِ غنيمت تقسيميږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16724, 'Isaiah 9:4', 'Isaiah', 9, 4, '&nbsp;تۀ به د هغوئ د غلامۍ جغ مات کړې او د هغوئ د اوږو نه به دروند بوج واخلې. او د ظالمانو زور به ختم کړې داسې لکه څنګه چې تا د ميديان لښکر تباه کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16725, 'Isaiah 9:5', 'Isaiah', 9, 5, '&nbsp;د هر يو جنګيالى فوجى پېزار او د هغوئ هغه ټولې جامې چې په وينو داغدارې دى، هغه به په اور وسوزولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16726, 'Isaiah 9:6', 'Isaiah', 9, 6, '&nbsp;زمونږ دپاره يو ماشوم پېدا شوے دے. مونږ له يو زوئ راکړے شوے دے. او حکمرانى به د هغۀ په اوږو وى. هغه به په دې نومونو سره ياديږى، ”عظيم مشير،“ ”خُدائ تعالىٰ،“ ”ابدى پلار“ او ”د امن شهزاده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16727, 'Isaiah 9:7', 'Isaiah', 9, 7, '&nbsp;د هغۀ شاهى طاقت به زياتيږى، د هغۀ بادشاهى به تل په امن کښې وى. هغه به د داؤد نه پس بادشاه وى، د هغۀ د بادشاهۍ بنياد به په صداقت او اِنصاف باندې قائم وى، د اوس نه واخله تر همېشه همېشه پورې به د هغۀ بادشاهى قائمه وى. د مالِک خُدائ ربُ الافواج غېرت به هم دغه شان وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16728, 'Isaiah 9:8', 'Isaiah', 9, 8, '&nbsp;مالِک خُدائ د يعقوب خلاف کلام کړے دے، او هغه په اِسرائيل مسلط دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16729, 'Isaiah 9:9', 'Isaiah', 9, 9, '&nbsp;د اِسرائيل ټول خلق او هغه هر يو کس چې په سامريه کښې اوسيږى، هغوئ ته به پته ولګى چې دا هغۀ کړى دى. خو اوس هغوئ مغروره او خود غرضه دى. هغوئ ووئيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16730, 'Isaiah 9:10', 'Isaiah', 9, 10, '&nbsp;”زمونږ د خښتو عمارتونه راغورزېدلى دى، خو مونږ به دا بيا د تراشلے شوو کاڼو نه جوړ کړُو. د چِنار ونې راماتې شوې دى، خو مونږ به د دې په ځائ د دِيار ښائسته ونې ولګوو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16731, 'Isaiah 9:11', 'Isaiah', 9, 11, '&nbsp;خو مالِک خُدائ د هغوئ دشمنان راپارولى دى چې په هغوئ باندې حمله وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16732, 'Isaiah 9:12', 'Isaiah', 9, 12, '&nbsp;د نمرخاتۀ طرف ته شام او د نمرپرېواتۀ طرف ته فلستيه خولۀ پرانستلې ده چې اِسرائيل ژوندے تېر کړى. خو د مالِک خُدائ غصه تر اوسه پورې سړه نۀ ده، او هغۀ د سزا دپاره تر اوسه پورې لاس اوچت نيولے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16733, 'Isaiah 9:13', 'Isaiah', 9, 13, '&nbsp;اګر چې مالِک خُدائ ربُ الافواج هغوئ له سزا هم ورکړې ده، خو د اِسرائيل خلقو توبه نۀ ده ويستلې، او هغوئ هغۀ ته واپس نۀ دى راګرځېدلى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16734, 'Isaiah 9:14', 'Isaiah', 9, 14, '&nbsp;صرف په يوه ورځ کښې به مالِک خُدائ د اِسرائيل مشرانو او خلقو له داسې سزا ورکړى چې د سر نه واخله تر بېخه پورې به ټول ختم کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16735, 'Isaiah 9:15', 'Isaiah', 9, 15, '&nbsp;مشران او عزتمند خلق د سر په شان دى او هغه پېغمبران د بېخ په شان دى چې د چا تعليمات د دروغو نه ډک وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16736, 'Isaiah 9:16', 'Isaiah', 9, 16, '&nbsp;د قوم مشرانو خلق بې‌لارې کړى دى او د تباهۍ په طرف يې روان کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16737, 'Isaiah 9:17', 'Isaiah', 9, 17, '&nbsp;نو مالِک خُدائ به د قوم د ځوانانو نه خوشحاله نۀ وى او هغه به په کونډو او يتيمانانو باندې هم رحم نۀ کوى، ځکه چې ټول خلق د خُدائ نه اوړېدلى دى او بدعمله شوى دى او هغوئ چې څۀ هم وائى هغه بدى وى. خو د مالِک خُدائ غصه به بيا هم نۀ سړيږى او هغۀ به د سزا ورکولو دپاره خپل لاس اوچت کړے وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16738, 'Isaiah 9:18', 'Isaiah', 9, 18, '&nbsp;د خلقو بدعملى د هغه اور په شان بليږى کوم چې د ازغو بوټى او غنې سوزوى. دا د ځنګل د هغه اور په شان بليږى کوم چې پاس په هوا کښې د لوږى ستنه جوړوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16739, 'Isaiah 9:19', 'Isaiah', 9, 19, '&nbsp;د مالِک خُدائ ربُ الافواج غصې سره به ټول مُلک وسوزى او په خلقو باندې به يې اور بَل وى او يو کس به په بل هيڅ ترس نۀ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16740, 'Isaiah 9:20', 'Isaiah', 9, 20, '&nbsp;هغوئ به خپل ګس طرف ته ګاونډيانو باندې حمله وکړى خو بيا به هم اوږې وى، په خپل ښې طرف ګاونډيانو باندې به حمله وکړى خو بيا به يې هم لوږه نۀ ختميږى. په آخر کښې به هغوئ خپل بچى هم وخورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16741, 'Isaiah 9:21', 'Isaiah', 9, 21, '&nbsp;منسى به په اِفرائيم او اِفرائيم به په منسى حمله وکړى، بيا به هغوئ يو ځائ په يهوداه حمله وکړى. خو د مالِک خُدائ غصه لا سړه نۀ ده، او هغۀ د سزا ورکولو دپاره لاس اوچت نيولے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16742, 'Isaiah 10:1', 'Isaiah', 10, 1, '&nbsp;په تاسو افسوس، تاسو د بې‌اِنصافۍ قانون جوړَوئ او د ظلم فتوې ورکوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16743, 'Isaiah 10:2', 'Isaiah', 10, 2, '&nbsp;او د دې په وجه غريبانانو خلقو له موقع نۀ ورکوئ چې هغوئ ته خپل حق مِلاو شى او د هغوئ سره اِنصاف وشى. او د دې قانون په وجه کونډې ستاسو په چال کښې راګېرې شى او يتيمان لوټ کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16744, 'Isaiah 10:3', 'Isaiah', 10, 3, '&nbsp;د عدالت په ورځ به تاسو څۀ کوئ؟ کله چې د يو لرې مُلک نه په تاسو يو افت راشى نو تاسو به څۀ کوئ؟ د مدد دپاره به تاسو کوم ځائ ته منډې وهئ؟ تاسو به خپل مال دولت چرته پټوئ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16745, 'Isaiah 10:4', 'Isaiah', 10, 4, '&nbsp;هيڅ به پاتې نۀ شى، يا خو به تاسو د قېديانو په مينځ کښې د يرې نه زېړې داړې نيولې وى او يا به په جنګ کښې ووژلے شئ. خو د مالِک خُدائ غصه به بيا هم نۀ سړيږى، هغۀ به تاسو له د سزا درکولو دپاره خپل لاس اوچت کړے وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16746, 'Isaiah 10:5', 'Isaiah', 10, 5, '&nbsp;بيا مالِک خُدائ وفرمائيل، ”اے اسوريانو، زۀ اسور د چُوکې په توګه استعمالوم چې هغه خلقو له سزا ورکړم چې زۀ چا ته غصه يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16747, 'Isaiah 10:6', 'Isaiah', 10, 6, '&nbsp;ما اسوريان ورولېږل چې په دې بې‌دينه قوم باندې حمله وکړى، دا هغه خلق دى چې زۀ يې غصه کړے يم. ما هغوئ د دې دپاره ورلېږل چې هغوئ وشوکوى او لوټ يې کړى او هغه خلق د لارې د خاورې په شان د پښو لاندې کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16748, 'Isaiah 10:7', 'Isaiah', 10, 7, '&nbsp;خو د اسور بادشاه په خپل زړۀ کښې د ظلم نه ډکې منصوبې لرلې. د هغۀ اراده دا وه چې ډېر قومونه تباه کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16749, 'Isaiah 10:8', 'Isaiah', 10, 8, '&nbsp;هغۀ وئيل چې، ”زما هر يو فوجى مشر بادشاه دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16750, 'Isaiah 10:9', 'Isaiah', 10, 9, '&nbsp;ما د کلنو، کرکميس، حمات او د ارفاد ښارونه فتح کړى دى. ما سامريه او دمشق فتح کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16751, 'Isaiah 10:10', 'Isaiah', 10, 10, '&nbsp;ما ډېر حکومتونه قابو کړى دى د چا معبودان چې د يروشلم او سامريه د بُتانو نه بهتر وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16752, 'Isaiah 10:11', 'Isaiah', 10, 11, '&nbsp;ما سامريه او د دې ټول بُتان تباه کړى دى او اوس به زۀ يروشلم او د هغې ټول بُتان هم تباه کړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16753, 'Isaiah 10:12', 'Isaiah', 10, 12, '&nbsp;خو مالِک خُدائ وفرمائيل، ”کله چې زۀ هغه کار ختم کړم چې د صيون غر او د يروشلم سره يې کوم، نو زۀ به د اسور بادشاه له د هغۀ د لافو او ټول غرور په وجه سزا ورکړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16754, 'Isaiah 10:13', 'Isaiah', 10, 13, '&nbsp;د اسور بادشاه به په خپلو لافو کښې وئيل، ”دا هر څۀ ما په خپل لاس کړى دى، ځکه چې زۀ ډېر هوښيار يم. ما د قومونو په مينځ کښې سرحدونه ختم کړى دى او د هغوئ خزانې مې لوټ کړى دى او د يو تکړه غوَيى په شان مې د هغې بادشاهان تباه کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16755, 'Isaiah 10:14', 'Isaiah', 10, 14, '&nbsp;ما د دُنيا قومونو نه دولت داسې اخستے دے لکه چې څوک د جالې نه هګۍ راوچتوى او ما داسې ټول مُلکونه هم را اوچت کړى دى، داسې يو وزر هم نۀ وو چې زۀ يې يرولے وے او نۀ داسې مخُوکه وه چې په ما باندې چغېدلے وے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16756, 'Isaiah 10:15', 'Isaiah', 10, 15, '&nbsp;خو مالِک خُدائ فرمائى، ”ولې يو تبر دا دعوىٰ کولے شى چې دا د هغه سړى نه تکړه دے چې څوک دا تبر استعمالوى؟ ولې يو آرا دا دعوىٰ کولے شى چې دا د هغه سړى نه تکړه ده چې څوک دا استعمالوى؟ يوه چُوکه سړے نۀ راپورته کوى بلکې سړے چُوکه راپورته کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16757, 'Isaiah 10:16', 'Isaiah', 10, 16, '&nbsp;نو په دې وجه به مالِک خُدائ ربُ الافواج يو داسې مرض راولېږى چې د اسور څربه جنګيالى به اوچ کلک شى. او د هغوئ لوئى به د اور په لمبو وسوزوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16758, 'Isaiah 10:17', 'Isaiah', 10, 17, '&nbsp;هغه مقدس ذات کوم چې د بنى اِسرائيل رڼا ده، هغه به د اور په شان شى. هغه به د يوې لمبې په شان شى، صرف په يوه ورځ کښې به د اسور د ازغو او غنو بوټى وسوزى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16759, 'Isaiah 10:18', 'Isaiah', 10, 18, '&nbsp;لوئ لوئ ځنګلونه او دا زرخېز پټى به بېخى داسې تباه شى لکه چې يو سخت مرض يو کس تباه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16760, 'Isaiah 10:19', 'Isaiah', 10, 19, '&nbsp;صرف د شمېر يو څو ونې به پاتې وى چې يو ماشوم يې هم شمېرلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16761, 'Isaiah 10:20', 'Isaiah', 10, 20, '&nbsp;په هغه وخت به ژوندى پاتې شوى اِسرائيليان يعنې د يعقوب د خاندان بچ شوى خلق نور په هغه قوم باندې اعتبار نۀ کوى چا چې دوئ وهلى وى. هغوئ به د زړۀ د اخلاصه په مالِک خُدائ باندې ايمان ولرى، کوم چې د بنى اِسرائيلو مقدس ذات دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16762, 'Isaiah 10:21', 'Isaiah', 10, 21, '&nbsp;باقى پاتې به راوګرځى، د يعقوب باقى پاتې حِصه به خُدائ تعالىٰ ته راوګرځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16763, 'Isaiah 10:22', 'Isaiah', 10, 22, '&nbsp;اګر چې اِسرائيل به د سمندر د شګو په شان بې‌شمېره وى، خو صرف يوه وړه پاتې شوې حِصه به راوګرځى. مالِک خُدائ د خپلو خلقو د تباه کولو صحيح فېصله کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16764, 'Isaiah 10:23', 'Isaiah', 10, 23, '&nbsp;نو بې‌شکه چې مالِک خُدائ پاک، ربُ الافواج به په ټول مُلک باندې تباهى راولى، لکه څنګه چې هغۀ فرمائيلى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16765, 'Isaiah 10:24', 'Isaiah', 10, 24, '&nbsp;مالِک خُدائ پاک ربُ الافواج فرمائى، ”اے په صيون کښې زما خلقو، د اسوريانو نه مۀ يرېږئ، اګر چې هغوئ په تاسو پسې چُوکه او ډنډه راخلى لکه څنګه به چې مخکښې مِصريانو درسره کول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16766, 'Isaiah 10:25', 'Isaiah', 10, 25, '&nbsp;ډېر لږ وخت پس به زۀ تاسو له سزا درکول بند کړم او بيا به زۀ هغوئ ته غصه شم او تباه به يې کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16767, 'Isaiah 10:26', 'Isaiah', 10, 26, '&nbsp;زۀ مالِک خُدائ ربُ الافواج به زما په خپله کوړه هغوئ داسې ووهم لکه څنګه مې چې د ميديان خلق د عوريب ګټ سره وهلى وُو. زۀ به اسوريانو له هغه شان سزا ورکړم لکه څنګه مې چې د مِصريانو لښکر په سمندر کښې ډوب کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16768, 'Isaiah 10:27', 'Isaiah', 10, 27, '&nbsp;کله چې هغه وخت راشى، نو زۀ به تاسو د اسوريانو د زور نه خلاص کړم او د هغوئ جغ به ستاسو د غاړو نه لرې کړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16769, 'Isaiah 10:28', 'Isaiah', 10, 28, '&nbsp;د دشمن لښکر د عيات ښار قبضه کړے دے. هغوئ د مجرون نه تېر شوى دى. او هغوئ خپل سامانونه په مِکماس کښې پرېښى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16770, 'Isaiah 10:29', 'Isaiah', 10, 29, '&nbsp;هغوئ د درې نه اوړېدلى دى او شپه به په جبعه کښې تېروى. د راما په ښار کښې خلق يرېدلى دى او د ساؤل بادشاه د ښار جبعې خلق تښتېدلى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16771, 'Isaiah 10:30', 'Isaiah', 10, 30, '&nbsp;د جليم خلقو چغې ووهئ. د ليس خلقو غوږ ونيسئ. او د عنتوت خلقو جواب راکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16772, 'Isaiah 10:31', 'Isaiah', 10, 31, '&nbsp;د مدمينه خلق وتښتېدل او جيبيم خلق د پناه دپاره منډې وهى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16773, 'Isaiah 10:32', 'Isaiah', 10, 32, '&nbsp;دشمن نن د نوب په ښار کښې دے او هغه د يروشلم په ښار کښې د صيون لور غر ته د دهمکۍ دپاره خپل لاس خوځوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16774, 'Isaiah 10:33', 'Isaiah', 10, 33, '&nbsp;خو ګورئ، مالِک خُدائ ربُ الافواج به هغوئ داسې لاندې راوغورزوى لکه چې د ونو نه څانګې څوک ماتوى. د هغوئ لوئ لوئ او مغروره خلق به راغورزولى وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16775, 'Isaiah 10:34', 'Isaiah', 10, 34, '&nbsp;هغه به تبر سره د ځنګل ونې راوغورزوى، داسې لکه څنګه چې د لبنان غټې ونې راغورزولے شوې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16776, 'Isaiah 11:1', 'Isaiah', 11, 1, '&nbsp;د يَسى مونډ به راوټوکيږى، او د هغې د جرړو نه به څانګه راوخېژى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16777, 'Isaiah 11:2', 'Isaiah', 11, 2, '&nbsp;د مالِک خُدائ روح به د هغۀ سره وى، او دا به د پوهې او حِکمت روح وى، د مشورې او د قوت روح، د عِلم او د مالِک خُدائ نه د يرې روح،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16778, 'Isaiah 11:3', 'Isaiah', 11, 3, '&nbsp;او هغۀ ته به د مالِک خُدائ په تابعدارۍ کښې خوشحالى ملاويږى. هغه به د خلقو په ظاهر صورت او د اورېدو په خبرو باندې عدالت نۀ کوى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16779, 'Isaiah 11:4', 'Isaiah', 11, 4, '&nbsp;هغه به اِنصاف سره د غريبانانو عدالت کوى، او هغه به اِنصاف سره د بې‌اسرى خلقو فېصله کوى. د هغۀ د کلام زور سره به زمکه رپيږى او د هغۀ د خولې يو پوکے به بدعمله تباه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16780, 'Isaiah 11:5', 'Isaiah', 11, 5, '&nbsp;صداقت به د هغۀ ملاتړ وى او وفادارى به د هغۀ کمربند وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16781, 'Isaiah 11:6', 'Isaiah', 11, 6, '&nbsp;شرمخان او ګډې به په يو ځائ په سکون سره اوسيږى، او پړانګ به د چېلو د بچو سره ملاست وى. د غواګانو او زمرو بچى به په يو ځائ خوراک کوى، او يو وړوکے ماشوم به دا بوتلے راوستے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16782, 'Isaiah 11:7', 'Isaiah', 11, 7, '&nbsp;غواګانې او مېلوګان به په يو ځائ خوراک کوى، او د هغوئ بچى به په يو ځائ په امن سره پراتۀ وى. او زمرے به د غوَيى په شان بوس خورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16783, 'Isaiah 11:8', 'Isaiah', 11, 8, '&nbsp;د پيو ماشوم به د مار سوړې سره لوبې کوى او لږ لوئ ماشوم به د زهرژن مار سوړه کښې لاس اچوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16784, 'Isaiah 11:9', 'Isaiah', 11, 9, '&nbsp;د خُدائ پاک په مقدس غر به هيڅ تباهى نۀ کيږى او نۀ به چا ته نقصان رسى، ځکه چې هغه مُلک به د مالِک خُدائ د عِلم نه داسې ډک وى لکه سمندرونه چې د اوبو نه ډک دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16785, 'Isaiah 11:10', 'Isaiah', 11, 10, '&nbsp;په هغه وخت به د يَسى د جرړې نه راټوکېدلې څانګه د قومونو دپاره د يوې جنډې نښه وى. قومونه به د هغۀ نه رهنمائى غواړى، او د هغۀ د استوګنې ځائ به جلالى وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16786, 'Isaiah 11:11', 'Isaiah', 11, 11, '&nbsp;کله چې هغه ورځ راشى، نو مالِک خُدائ به يو ځل بيا د خپل طاقت نه کار واخلى او خپل هغه خلق به خپلو کورونو ته راولى کوم چې په اسور، مِصر، فتروس، ايتهوپيا، عيلام، بابل او د حمات په مُلکونو کښې او د سمندر په غاړو کښې پاتې شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16787, 'Isaiah 11:12', 'Isaiah', 11, 12, '&nbsp;مالِک خُدائ به د نښې دپاره يوه جنډا راواخلى چې قومونو ته وښائى چې هغه يو ځل بيا د اِسرائيل او د يهوداه خوارۀ وارۀ خلق راغونډوى او د دُنيا د څلورو واړو سرونو نه يې واپس راولى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16788, 'Isaiah 11:13', 'Isaiah', 11, 13, '&nbsp;د اِسرائيل حسد به ختم شى او د يهوداه د دشمنانو نام و نشان به ختم شى. اِسرائيل به د يهوداه نه نور نفرت نۀ کوى او نۀ به يهوداه د اِسرائيل سره دشمنى کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16789, 'Isaiah 11:14', 'Isaiah', 11, 14, '&nbsp;هغوئ به په يو ځائ د نمرپرېواتۀ طرف په فلستيانو باندې حمله وکړى او چې د نمرخاتۀ طرف ته کوم خلق اوسيږى نو هغوئ به لوټ کړى. هغوئ به د ادوم او موآب په خلقو باندې فتح حاصله کړى او د عمون خلق به د هغوئ تابعدار شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16790, 'Isaiah 11:15', 'Isaiah', 11, 15, '&nbsp;مالِک خُدائ به بحرِقُلزم اوچ کړى او هغه به خپل لاس د فرات سيند طرف ته اوچت کړى او يوه ګرمه هوا به راولېږى او د دې نه به اووۀ واړۀ نِهرونه جوړ کړى، چې هغوئ په اوچه زمکه په آسانۍ تېر شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16791, 'Isaiah 11:16', 'Isaiah', 11, 16, '&nbsp;هلته چې د هغۀ کوم خپل خلق يعنې بنى اِسرائيليان ژوندى پاتې وى نو د هغوئ دپاره به يو لوئ سړک وى چې د اسور نه به ووځى، هغسې لکه څنګه چې د هغوئ پلار نيکۀ دپاره يوه لار جوړه وه کله چې هغوئ د مِصر نه روان شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16792, 'Isaiah 12:1', 'Isaiah', 12, 1, '&nbsp;په هغه ورځ به تاسو وايئ، ”اے مالِکه خُدايه، زۀ ستا ثناء صِفت کوم. تۀ ما ته غصه وې، خو اوس ستا غصه سړه شوې ده او تۀ ما له تسلى راکوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16793, 'Isaiah 12:2', 'Isaiah', 12, 2, '&nbsp;ګورئ، خُدائ پاک زما خلاصونکے دے، زۀ به په هغۀ توکل کوم او نۀ به يرېږم. ځکه چې مالِک خُدائ ما له طاقت راکوى او زما حفاظت کوى، هغه زما خلاصونکے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16794, 'Isaiah 12:3', 'Isaiah', 12, 3, '&nbsp;په خوشحالۍ سره به تاسو د خلاصون د چشمې نه اوبۀ راوباسئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16795, 'Isaiah 12:4', 'Isaiah', 12, 4, '&nbsp;په هغه ورځ به تاسو وايئ، ”د مالِک خُدائ شُکر ادا کړئ. هغۀ ته د مدد دپاره آواز وکړئ. هغۀ چې څۀ کړى دى نو ټولو قومونو ته ووايئ. هغوئ ته ووايئ چې د هغۀ نوم څومره لوئ دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16796, 'Isaiah 12:5', 'Isaiah', 12, 5, '&nbsp;مالِک خُدائ چې کوم لوئ لوئ کارونه کړى دى نو د هغې په وجه د هغۀ حمد‌و‌ثناء کوئ. او ټولې دُنيا ته دې د دې خبر ورسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16797, 'Isaiah 12:6', 'Isaiah', 12, 6, '&nbsp;اے د صيون خلقو په اوچت آواز د خوشحالۍ نعرې ووهئ. د بنى اِسرائيلو مقدس ذات ډېر لوئ دے، او هغه د خپلو خلقو په مينځ کښې اوسيږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16798, 'Isaiah 13:1', 'Isaiah', 13, 1, '&nbsp;دا د بابل په حقله يو پېغام دے چې د آموص زوئ يشعياه ته څرګند شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16799, 'Isaiah 13:2', 'Isaiah', 13, 2, '&nbsp;په اوچت غر د جنګ جنډا اوچته کړه. هغوئ ته چغه ووهه او لاسونو سره اِشاره ورکړه چې راشى او د هغه مغروره ښار په دروازو کښې ورداخل شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16800, 'Isaiah 13:3', 'Isaiah', 13, 3, '&nbsp;ما مالِک خُدائ دا فوجيان راغوښتى دى، آو، ما دا تکړه جنګياليان راغوښتى دى چې زما غصه څرګنده کړى، او چې زما لوئى وشى نو هغوئ به خوشحالى وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');